Method.Implementation:
Set tSC=ADAPTER.setFilePath(pFileDir,.tOldDir) If $$$ISERR(tSC) { $$$LOGSTATUS(tSC) Quit 0 }
Set tOK=$S(ADAPTER.%isSFTP:ADAPTER.FTP.DeleteSSH(pFilename),1:ADAPTER.FTP.Delete(pFilename))

if 'tOK

{

   if ADAPTER.Connected set tSC=ADAPTER.Disconnect(1)
   Set tSC=ADAPTER.Connect(ADAPTER.ConnectTimeout,1)
   Set tOK=$S(ADAPTER.%isSFTP:ADAPTER.FTP.DeleteSSH(pFilename),1:ADAPTER.FTP.Delete(pFilename))

}
Do:'tOK ADAPTER.disconnectOnNetErr(,1)
If ADAPTER.Connected { Set tSC=ADAPTER.restoreFilePath(tOldDir) If $$$ISERR(tSC) $$$LOGSTATUS(tSC) Quit 0 }
Quit tOK
